rules = ["replace('c','g')", "replace('a','e')", "replace('g','h')", "replace('f','b')"]

# Apply rules sequentially to each input
def apply_rule(text, rule_str):
    # Parse the rule string
    # Format: replace('pattern','replacement')
    start = rule_str.find("'") + 1
    end = rule_str.find("'", start)
    pattern = rule_str[start:end]

    start = rule_str.rfind("'") + 1
    end = rule_str.rfind("'")
    replacement = rule_str[start:end]

    return text.replace(pattern, replacement)

def apply_all_rules(text, rules_list):
    result = text
    for rule in rules_list:
        result = apply_rule(result, rule)
    return result

